import{_ as e,o as t,c as i,a2 as o}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"Tabla Cronológica Sintética","description":"","frontmatter":{},"headers":[],"relativePath":"es/93-编年史简表.md","filePath":"es/93-编年史简表.md"}'),r={name:"es/93-编年史简表.md"};function d(l,a,s,n,c,m){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="tabla-cronologica-sintetica" tabindex="-1">Tabla Cronológica Sintética <a class="header-anchor" href="#tabla-cronologica-sintetica" aria-label="Permalink to &quot;Tabla Cronológica Sintética&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>93</td></tr><tr><td>Módulo</td><td>Apéndices y Materiales de Referencia</td></tr><tr><td>Palabras clave</td><td>cronología, división de eras, acontecimientos mayores, hitos históricos, Universo Hengyuan</td></tr></tbody></table><h2 id="i-notas-sobre-la-cronologia" tabindex="-1">I. Notas sobre la cronología <a class="header-anchor" href="#i-notas-sobre-la-cronologia" aria-label="Permalink to &quot;I. Notas sobre la cronología&quot;">​</a></h2><p>Esta tabla registra, sobre la base del tiempo estándar del Universo Hengyuan, los principales acontecimientos históricos y los hitos clave del desarrollo de la Civilización Simbiótica del Ancla, ordenados por eras. El lapso temporal se extiende desde el período antiguo de la era pre-Ancla hasta las perspectivas futuras de la era de la simbiosis interestelar. Cada era indica su inicio y su fin, sus rasgos característicos y sus acontecimientos mayores. Esta tabla es un índice histórico altamente condensado; para la historia detallada de cada era, véanse los relatos dedicados en los documentos 70-79.</p><h2 id="ii-panorama-general-de-la-division-de-eras" tabindex="-1">II. Panorama general de la división de eras <a class="header-anchor" href="#ii-panorama-general-de-la-division-de-eras" aria-label="Permalink to &quot;II. Panorama general de la división de eras&quot;">​</a></h2><table tabindex="0"><thead><tr><th>N.º de era</th><th>Nombre de la era</th><th>Período (años estándar del Universo Hengyuan)</th><th>Duración</th><th>Rasgos principales</th></tr></thead><tbody><tr><td>Primera era</td><td>Era pre-Ancla</td><td>aprox. −10 mil millones a −10 000 años</td><td>aprox. 10 mil millones de años</td><td>Dominaban los sistemas de cultivo depredador; las civilizaciones ascendían y caían en ciclos</td></tr><tr><td>Segunda era</td><td>Era del Despertar del Ancla</td><td>−10 000 a −1000 años</td><td>aprox. 9000 años</td><td>El mecanismo del Ancla fue descubierto y aplicado inicialmente</td></tr><tr><td>Tercera era</td><td>Período de establecimiento del sistema simbiótico</td><td>−1000 a −100 años</td><td>aprox. 900 años</td><td>El marco institucional de la Civilización Simbiótica del Ancla se estableció gradualmente</td></tr><tr><td>Cuarta era</td><td>Período de apertura de los Trescientos Sistemas</td><td>−100 a −50 años</td><td>aprox. 50 años</td><td>Los Trescientos Sistemas de Cultivo de Origen se abrieron por completo</td></tr><tr><td>Quinta era</td><td>Período de la Estrategia de Activación del 20 %</td><td>−50 años al año uno</td><td>aprox. 50 años</td><td>El 20 % de los seres vivos fue activado como Potencias Supremas del Plano</td></tr><tr><td>Sexta era</td><td>Era de la primera ascensión</td><td>año uno a 100</td><td>100 años</td><td>La civilización simbiótica logró su primera ascensión por etapas</td></tr><tr><td>Séptima era</td><td>Era de la República de las Diez Mil Razas</td><td>100 a 500</td><td>400 años</td><td>La República de las Diez Mil Razas se estableció formalmente; se profundizó la integración interracial</td></tr><tr><td>Octava era</td><td>Era de la exploración transplanar</td><td>500 a 2000</td><td>1500 años</td><td>Se desplegaron actividades de exploración y arqueología transplanar a gran escala</td></tr><tr><td>Novena era</td><td>Era de la simbiosis interestelar</td><td>2000 al futuro</td><td>en curso</td><td>Se completó una red de simbiosis a escala universal; avanzó la ascensión global</td></tr></tbody></table><p>Nota: «año uno» se refiere al año de la proclamación formal de la Civilización Simbiótica del Ancla, que sirve como punto de división de este calendario histórico.</p><h2 id="iii-la-era-pre-ancla-aprox-−10-mil-millones-a-−10-000-anos" tabindex="-1">III. La era pre-Ancla (aprox. −10 mil millones a −10 000 años) <a class="header-anchor" href="#iii-la-era-pre-ancla-aprox-−10-mil-millones-a-−10-000-anos" aria-label="Permalink to &quot;III. La era pre-Ancla (aprox. −10 mil millones a −10 000 años)&quot;">​</a></h2><p>La era pre-Ancla fue la era más larga de la historia del Universo Hengyuan, con una duración de aproximadamente diez mil millones de años. Su rasgo central fue el dominio de los sistemas de cultivo depredador sobre el universo, con civilizaciones repitiéndose sin cesar en el ciclo de «auge — cénit — depredación — colapso».</p><table tabindex="0"><thead><tr><th>Hito temporal</th><th>Acontecimiento mayor</th></tr></thead><tbody><tr><td>aprox. −10 mil millones de años</td><td>La red de leyes del Universo Hengyuan se estabilizó; se formaron los primeros planos materiales; el universo entró en un estado habitable</td></tr><tr><td>aprox. −8 mil millones de años</td><td>Las primeras vidas inteligentes surgieron en múltiples planos materiales; los sistemas de cultivo primitivos comenzaron a germinar</td></tr><tr><td>aprox. −5 mil millones de años</td><td>Los sistemas de cultivo depredador se volvieron gradualmente dominantes; los fuertes alcanzaron una evolución rápida devorando a los débiles</td></tr><tr><td>aprox. −3 mil millones de años</td><td>Estalló la primera guerra de depredación a escala universal; las civilizaciones de varias regiones estelares sufrieron golpes devastadores</td></tr><tr><td>aprox. −1 mil millones de años</td><td>Comenzaron a manifestarse los defectos del sistema depredador; se aceleró el aumento global de la entropía del universo; los recursos de cultivo se agotaron gradualmente</td></tr><tr><td>aprox. −500 millones de años</td><td>Aparecieron los primeros pensadores que reflexionaban sobre el sistema depredador; comenzaron a germinar los brotes del pensamiento simbiótico</td></tr><tr><td>aprox. −100 millones de años</td><td>Surgieron pequeñas civilizaciones experimentales simbióticas en varias regiones estelares, pero todas fueron destruidas por las civilizaciones depredadoras</td></tr><tr><td>aprox. −1 millón de años</td><td>El universo en su conjunto entró en la «Gran Decadencia»; tanto el número de civilizaciones como el nivel de cultivo cayeron a mínimos históricos</td></tr><tr><td>aprox. −10 000 años</td><td>Un cultivador del Primer Plano, durante un largo cultivo, percibió accidentalmente un nodo estable en la red de leyes; el mecanismo del Ancla fue descubierto por primera vez</td></tr></tbody></table><h2 id="iv-la-era-del-despertar-del-ancla-−10-000-a-−1000-anos" tabindex="-1">IV. La Era del Despertar del Ancla (−10 000 a −1000 años) <a class="header-anchor" href="#iv-la-era-del-despertar-del-ancla-−10-000-a-−1000-anos" aria-label="Permalink to &quot;IV. La Era del Despertar del Ancla (−10 000 a −1000 años)&quot;">​</a></h2><p>La Era del Despertar del Ancla fue el período de transición del mecanismo del Ancla desde el descubrimiento hasta la aplicación inicial. Su rasgo central fue la maduración gradual de la tecnología del Ancla y la difusión del pensamiento simbiótico.</p><table tabindex="0"><thead><tr><th>Hito temporal</th><th>Acontecimiento mayor</th></tr></thead><tbody><tr><td>−10 000 años</td><td>El mecanismo del Ancla fue descubierto por primera vez; su descubridor lo denominó el «Ancla» y comenzó una investigación sistemática</td></tr><tr><td>−9000 años</td><td>Se estableció con éxito el primer Ancla artificial, demostrando que los Anclas podían construirse y mantenerse artificialmente</td></tr><tr><td>−8000 años</td><td>La tecnología del Ancla comenzó a difundirse en un ámbito reducido; aparecieron los primeros cultivadores del Ancla</td></tr><tr><td>−7000 años</td><td>Se descubrió que los Anclas podían servir de referencia para las conexiones transplanar; tuvo éxito el primer viaje entre planos asistido por Ancla del que se tiene registro</td></tr><tr><td>−6000 años</td><td>El pensamiento simbiótico comenzó a combinarse con la tecnología del Ancla; se publicaron los primeros textos teóricos sobre la «Simbiosis del Ancla»</td></tr><tr><td>−5000 años</td><td>Se estableció la primera ciudad-estado simbiótica basada en el Ancla, demostrando la viabilidad del sistema simbiótico</td></tr><tr><td>−4000 años</td><td>Las civilizaciones depredadoras atacaron las ciudades-estado simbióticas; estas se defendieron con éxito gracias a la tecnología del Ancla</td></tr><tr><td>−3000 años</td><td>El pensamiento simbiótico se difundió en varias regiones estelares; cada vez más civilizaciones comenzaron a intentar la transición simbiótica</td></tr><tr><td>−2000 años</td><td>Se celebró la primera «Gran Asamblea de Simbiosis de las Diez Mil Razas»; representantes de decenas de razas debatieron conjuntamente el futuro de la civilización simbiótica</td></tr><tr><td>−1000 años</td><td>La tecnología del Ancla y el pensamiento simbiótico habían adquirido las condiciones para establecer una civilización unificada; comenzó el Período de establecimiento del sistema simbiótico</td></tr></tbody></table><h2 id="v-el-periodo-de-establecimiento-del-sistema-simbiotico-−1000-a-−100-anos" tabindex="-1">V. El Período de establecimiento del sistema simbiótico (−1000 a −100 años) <a class="header-anchor" href="#v-el-periodo-de-establecimiento-del-sistema-simbiotico-−1000-a-−100-anos" aria-label="Permalink to &quot;V. El Período de establecimiento del sistema simbiótico (−1000 a −100 años)&quot;">​</a></h2><p>El Período de establecimiento del sistema simbiótico fue el período crucial en el que el marco institucional de la Civilización Simbiótica del Ancla se creó desde la nada.</p><table tabindex="0"><thead><tr><th>Hito temporal</th><th>Acontecimiento mayor</th></tr></thead><tbody><tr><td>−1000 años</td><td>Se estableció el Comité de Redacción de la Constitución Simbiótica y comenzó la redacción de la ley fundamental</td></tr><tr><td>−950 años</td><td>Se completó el proyecto de la Constitución Simbiótica; se solicitaron ampliamente las opiniones de las diez mil razas</td></tr><tr><td>−900 años</td><td>La Constitución Simbiótica fue aprobada por referéndum popular y entró en vigor; se proclamó la Civilización Simbiótica del Ancla</td></tr><tr><td>−850 años</td><td>Las tres grandes instituciones — la Asamblea Legislativa del Ancla, el Comité Ejecutivo Simbiótico y el Tribunal Simbiótico — se establecieron formalmente y comenzaron a funcionar</td></tr><tr><td>−800 años</td><td>El Mecanismo de Contrato Vinculado a la Producción comenzó a promoverse en todo el territorio</td></tr><tr><td>−700 años</td><td>Leyes fundamentales como la Ley Simbiótica del Trabajo y la Ley de Protección al Consumidor fueron promulgadas sucesivamente</td></tr><tr><td>−600 años</td><td>Las cinco leyes complementarias sobre educación, atención médica, vivienda, medio ambiente y antimonopolio fueron todas promulgadas y puestas en práctica</td></tr><tr><td>−500 años</td><td>Se lanzaron oficialmente los trabajos de excavación y compilación de los Trescientos Sistemas de Cultivo de Origen</td></tr><tr><td>−400 años</td><td>Los primeros cincuenta Sistemas de Cultivo de Origen completaron su compilación y verificación</td></tr><tr><td>−300 años</td><td>Se lograron avances en la aplicación tecnológica del Fruto Multiplicador; maduró la tecnología de amplificación deductiva centuplicada</td></tr><tr><td>−200 años</td><td>Los Trescientos Sistemas completaron todos su compilación y entraron en la etapa final de verificación de seguridad</td></tr><tr><td>−100 años</td><td>Maduraron las condiciones para la apertura completa de los Trescientos Sistemas de Cultivo de Origen; comenzó el período de apertura</td></tr></tbody></table><h2 id="vi-el-periodo-de-apertura-de-los-trescientos-sistemas-−100-a-−50-anos" tabindex="-1">VI. El Período de apertura de los Trescientos Sistemas (−100 a −50 años) <a class="header-anchor" href="#vi-el-periodo-de-apertura-de-los-trescientos-sistemas-−100-a-−50-anos" aria-label="Permalink to &quot;VI. El Período de apertura de los Trescientos Sistemas (−100 a −50 años)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Hito temporal</th><th>Acontecimiento mayor</th></tr></thead><tbody><tr><td>−100 años</td><td>Los Trescientos Sistemas de Cultivo de Origen se abrieron formalmente de forma gratuita a todos los seres vivos del universo</td></tr><tr><td>−90 años</td><td>El número de cultivadores se multiplicó por cien en diez años; «un camino para cada uno» se realizó preliminarmente</td></tr><tr><td>−80 años</td><td>Las Tres Bases de Origen (Iteración por Deducción, Ciclo de Vida y despacho de principios legales espaciales) se convirtieron en los sistemas más populares</td></tr><tr><td>−70 años</td><td>Aparecieron los primeros cultivadores que alcanzaron altos niveles mediante los nuevos sistemas, demostrando la eficacia de estos</td></tr><tr><td>−60 años</td><td>Se estableció por completo la red de mentores; los cultivadores avanzados comenzaron a cumplir su deber legal de guiar a los cultivadores principiantes</td></tr><tr><td>−50 años</td><td>El nivel de cultivo general de toda la población mejoró sustancialmente; maduraron las condiciones de la Estrategia de Activación del 20 %</td></tr></tbody></table><h2 id="vii-el-periodo-de-la-estrategia-de-activacion-del-20-−50-anos-al-ano-uno" tabindex="-1">VII. El Período de la Estrategia de Activación del 20 % (−50 años al año uno) <a class="header-anchor" href="#vii-el-periodo-de-la-estrategia-de-activacion-del-20-−50-anos-al-ano-uno" aria-label="Permalink to &quot;VII. El Período de la Estrategia de Activación del 20 % (−50 años al año uno)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Hito temporal</th><th>Acontecimiento mayor</th></tr></thead><tbody><tr><td>−50 años</td><td>La Estrategia de Activación del 20 % se lanzó oficialmente, con el objetivo de activar al 20 % de los seres vivos como Potencias Supremas del Plano en 50 años</td></tr><tr><td>−40 años</td><td>Nacieron las primeras Potencias Supremas del Plano; la tasa de activación alcanzó el 5 %</td></tr><tr><td>−30 años</td><td>La tasa de activación alcanzó el 10 %; las Potencias Supremas del Plano comenzaron a desempeñar un papel central en el mantenimiento de los Anclas</td></tr><tr><td>−20 años</td><td>La tasa de activación alcanzó el 15 %; el nivel de cultivo general del universo logró un salto cualitativo</td></tr><tr><td>−10 años</td><td>La tasa de activación alcanzó el 18 %, acercándose al objetivo estratégico</td></tr><tr><td>Año uno</td><td>La tasa de activación alcanzó el 20,3 %; la Estrategia de Activación del 20 % se cumplió con pleno éxito, y la Civilización Simbiótica del Ancla entró en una nueva era</td></tr></tbody></table><h2 id="viii-la-era-de-la-primera-ascension-ano-uno-a-100" tabindex="-1">VIII. La Era de la primera ascensión (año uno a 100) <a class="header-anchor" href="#viii-la-era-de-la-primera-ascension-ano-uno-a-100" aria-label="Permalink to &quot;VIII. La Era de la primera ascensión (año uno a 100)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Hito temporal</th><th>Acontecimiento mayor</th></tr></thead><tbody><tr><td>Año uno</td><td>La civilización simbiótica proclamó formalmente su entrada en la era de la ascensión; se completó la primera etapa de la Vía de Ascensión en Cuatro Etapas (Cimentación de la Realidad)</td></tr><tr><td>20</td><td>La segunda etapa (Empoderamiento Tecnológico) avanzó en todos los frentes; las leyes de cultivo y la ingeniería tecnológica se integraron profundamente</td></tr><tr><td>40</td><td>Las tecnologías del Espejo de Réplica y del espacio aislado lograron producción en serie a escala industrial; la arqueología transplanar entró en la era de la escala</td></tr><tr><td>60</td><td>Los primeros cultivadores de ascensión de la conciencia alcanzaron niveles altos; comenzó la tercera etapa (Evolución de la Conciencia)</td></tr><tr><td>80</td><td>Se completó la construcción de las infraestructuras del dominio de la conciencia; la tecnología de migración de la conciencia maduró preliminarmente</td></tr><tr><td>100</td><td>La primera ascensión por etapas tuvo éxito; la civilización simbiótica en su conjunto fue elevada en medio nivel de dimensión</td></tr></tbody></table><h2 id="ix-la-era-de-la-republica-de-las-diez-mil-razas-100-a-500" tabindex="-1">IX. La Era de la República de las Diez Mil Razas (100 a 500) <a class="header-anchor" href="#ix-la-era-de-la-republica-de-las-diez-mil-razas-100-a-500" aria-label="Permalink to &quot;IX. La Era de la República de las Diez Mil Razas (100 a 500)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Hito temporal</th><th>Acontecimiento mayor</th></tr></thead><tbody><tr><td>100</td><td>Se proclamó formalmente la República de las Diez Mil Razas; todas las razas inteligentes lograron una unión igualitaria dentro del marco de la civilización simbiótica</td></tr><tr><td>150</td><td>El Registro de las Diez Mil Razas completó su compilación, recogiendo todas las razas inteligentes conocidas</td></tr><tr><td>200</td><td>Los matrimonios interraciales y la fusión cultural se convirtieron en la norma; comenzaron a aparecer nuevas razas mixtas</td></tr><tr><td>300</td><td>Se completó la promoción de la lengua común de las diez mil razas; las barreras de comunicación interracial quedaron prácticamente eliminadas</td></tr><tr><td>400</td><td>Las culturas de las Diez Mil Razas vivieron una gran prosperidad; las culturas tradicionales de cada pueblo fueron protegidas y desarrolladas dentro del marco simbiótico</td></tr><tr><td>500</td><td>La República de las Diez Mil Razas entró en su período de madurez; maduraron plenamente las condiciones de la exploración transplanar</td></tr></tbody></table><h2 id="x-la-era-de-la-exploracion-transplanar-500-a-2000" tabindex="-1">X. La Era de la exploración transplanar (500 a 2000) <a class="header-anchor" href="#x-la-era-de-la-exploracion-transplanar-500-a-2000" aria-label="Permalink to &quot;X. La Era de la exploración transplanar (500 a 2000)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Hito temporal</th><th>Acontecimiento mayor</th></tr></thead><tbody><tr><td>500</td><td>Se lanzó oficialmente el programa de exploración transplanar a gran escala; se estableció la Administración de Planos</td></tr><tr><td>600</td><td>Se exploraron más de mil planos; se completó preliminarmente la base maestra de coordenadas de planos</td></tr><tr><td>800</td><td>El esquema de arqueología a distancia mediante Espejo de Réplica maduró plenamente; la arqueología transplanar entró en su edad de oro</td></tr><tr><td>1000</td><td>Se lograron avances en la tecnología de regresión temporal; se estableció formalmente el principio de observar primero y luego intervenir dentro de límites</td></tr><tr><td>1200</td><td>Se exploraron más de cien mil planos; se establecieron relaciones diplomáticas con decenas de civilizaciones de otros planos</td></tr><tr><td>1500</td><td>Las directrices éticas transplanar se implementaron plenamente; la interacción entre civilizaciones entró en la era de la regulación</td></tr><tr><td>1800</td><td>El mecanismo de prevención y control de paradojas temporales maduró por completo; la arqueología de regresión temporal alcanzó escala</td></tr><tr><td>2000</td><td>La exploración transplanar logró resultados espléndidos; maduraron plenamente las condiciones de la Era de la simbiosis interestelar</td></tr></tbody></table><h2 id="xi-la-era-de-la-simbiosis-interestelar-2000-al-futuro" tabindex="-1">XI. La Era de la simbiosis interestelar (2000 al futuro) <a class="header-anchor" href="#xi-la-era-de-la-simbiosis-interestelar-2000-al-futuro" aria-label="Permalink to &quot;XI. La Era de la simbiosis interestelar (2000 al futuro)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Hito temporal</th><th>Acontecimiento mayor</th></tr></thead><tbody><tr><td>2000</td><td>La Era de la simbiosis interestelar comenzó formalmente; la cuarta etapa (Simbiosis Interestelar) avanzó en todos los frentes</td></tr><tr><td>2500 (perspectiva)</td><td>La red de Anclas a escala universal se completó preliminarmente, cubriendo todos los planos explorados</td></tr><tr><td>3000 (perspectiva)</td><td>El sistema de simbiosis transplanar maduró; las Diez Mil Razas lograron una verdadera simbiosis en el ámbito del universo</td></tr><tr><td>5000 (perspectiva)</td><td>Se completó la ascensión global del universo; el Universo Hengyuan entró en un estado de existencia de mayor dimensión</td></tr><tr><td>El futuro (perspectiva)</td><td>La Civilización Simbiótica del Ancla continúa explorando más allá del universo, difundiendo el ideal de la simbiosis hacia existencias más amplias</td></tr></tbody></table><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>La tabla cronológica es la epopeya de lucha de la Civilización Simbiótica del Ancla — de la ignorancia al despertar, de la debilidad a la fuerza, de su propio plano al universo entero. La sucesión de cada era es testimonio de la victoria del ideal simbiótico sobre el ideal depredador y del progreso civilizado sobre la decadencia bárbara. La historia no es el polvo del pasado, sino la semilla del futuro: comprender esta historia es comprender de dónde vino la civilización simbiótica y hacia dónde se dirige.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>70-纪元划分总表 (Tabla Maestra de la División de Eras)</li><li>72-锚点觉醒纪元 (La Era del Despertar del Ancla)</li><li>79-星际共生时代展望 (Las Perspectivas de la Era de la Simbiosis Interestelar)</li></ul>',32)])])}const b=e(r,[["render",d]]);export{u as __pageData,b as default};
